        public static readonly string[] FaqA = { "1. Öffne im Menü (⋯) den Packs-Ordner.\n2. Kopiere den Ordner „Default“ und gib der Kopie einen Namen, z. B. „Mein Pack“. Default enthält alle Original-Icons und ist die perfekte Vorlage.\n3. Ersetze darin die PNG-Bilder, die du ändern möchtest. Dateiname und Unterordner müssen genau gleich bleiben.\n4. Bilder, die du nicht änderst, kannst du löschen – im Spiel bleibt dann einfach das Original.\n5. Optional: Lege ein Vorschaubild „preview.jpg“ in den Pack-Ordner (am besten 21:9, z. B. 2100 × 900 Pixel).\n6. In FogForge auf „Packs neu laden“ klicken – dein Pack erscheint links.", "• PNG mit transparentem Hintergrund.\n• Am besten dieselbe Größe wie das Original – öffne einfach die Datei im Default-Pack und schau nach (Icons meist 256 × 256, Porträts 512 × 512).\n• Der Dateiname muss exakt gleich sein, sonst erkennt das Spiel das Bild nicht.\n• Perks, Opfergaben & Co. sollten das Motiv mittig haben, damit nichts vom Rahmen im Spiel abgeschnitten wird.", "Die Ordner sind wie im Spiel aufgebaut:\n• CharPortraits – Porträts\n• Perks – Perks\n• Powers – Kräfte\n• items – Items\n• ItemAddons – Add-ons\n• Favors – Opfergaben\n• StoreBackgrounds – Store-Bilder\n\nUnterordner wie „DLC5“ oder „Wales“ stehen für Kapitel. Tipp: Im Default-Pack mit der Windows-Suche nach dem Namen suchen, z. B. „Trapper“ oder „Huntress“.", "Nichts geht verloren. Bevor ein Pack geladen wird, sichert FogForge jedes Original, das ersetzt wird, im Ordner „Backup“.\n\nMit „Entladen“ werden alle Originale zurückgeschrieben. Beim Wechsel zu einem anderen Pack passiert das automatisch.\n\nDas Default-Pack enthält außerdem eine komplette Kopie der Original-Icons.", "FogForge tauscht nur Bilddateien im Icons-Ordner des Spiels aus. Es verändert keine .pak-Dateien, keinen Spielcode und greift nicht in das laufende Spiel ein.\n\nIcon-Packs dieser Art sind in der Community seit Jahren verbreitet und gelten nach allem, was bekannt ist, als unbedenklich. Eine offizielle Garantie des Entwicklers gibt es aber nicht – die Nutzung erfolgt auf eigene Verantwortung.", "Spiel-Updates oder „Dateien überprüfen“ in Steam können die Original-Icons wiederherstellen. Aktiviere das Pack in FogForge einfach noch einmal – fertig.\n\nNeue Icons aus einem Update bleiben original, bis ein Pack sie ebenfalls enthält.", "Klicke oben rechts auf „Spiel nicht gefunden“ und wähle den Ordner von Dead by Daylight, z. B.:\n…\\steamapps\\common\\Dead by Daylight\n\nDu kannst auch direkt den Icons-Ordner wählen:\n…\\DeadByDaylight\\Content\\UI\\Icons\n\nDas funktioniert auch mit der Epic- oder Microsoft-Store-Version.", "1. Wähle das Pack links aus.\n2. Öffne das Menü (⋯) und klicke auf „Ausgewähltes Pack als ZIP speichern“.\n3. Schick die ZIP-Datei deinem Freund.\n4. Er entpackt sie in den Packs-Ordner seines FogForge – fertig.", "Damit legst du fest, welche Kategorien ins Spiel geladen werden – zum Beispiel nur Perks und Porträts, während alles andere original bleibt.\n\nÄnderst du die Schalter, während ein Pack aktiv ist, erscheint „Änderungen übernehmen“. Ein Klick lädt das Pack mit deiner neuen Auswahl." };

        public static string SystemCode()
        {
            try
            {
                var c = CultureInfo.CurrentUICulture.TwoLetterISOLanguageName.ToLowerInvariant();
                return Codes.Contains(c) ? c : "en";
            }
            catch { return "en"; }
        }
        public static string Name(string code) { int i = Array.IndexOf(Codes, code); return i < 0 ? code : Names[i]; }

        static readonly Dictionary<string, string[]> tab = new Dictionary<string, string[]>();
        static void A(string de, params string[] t) { tab[de] = t; }

        public static string T(string de)
        {
            if (Code == "de" || de == null) return de;
            string[] t; int i = Array.IndexOf(Codes, Code) - 1;
            if (i >= 0 && tab.TryGetValue(de, out t) && i < t.Length && !string.IsNullOrEmpty(t[i])) return t[i];
            if (tab.TryGetValue(de, out t) && t.Length > 0) return t[0];
            return de;
        }
        public static string F(string de, params object[] a) { return string.Format(T(de), a); }

