        // ---------------- Flaggen (selbst gezeichnet, Windows kennt keine Flaggen-Emojis) ----------------
        public static void Flag(Graphics g, string code, RectangleF r)
        {
            var st = g.Save();
            g.SmoothingMode = SmoothingMode.AntiAlias;
            using (var clip = UI.Round(r, r.Height * 0.18f))
            {
                g.SetClip(clip, CombineMode.Intersect);
                float x = r.X, y = r.Y, w = r.Width, h = r.Height;
                Action<Color, float, float, float, float> R = (c, a, b, cw, ch) => { using (var br = new SolidBrush(c)) g.FillRectangle(br, x + a * w, y + b * h, cw * w + 0.5f, ch * h + 0.5f); };
                switch (code)
                {
                    case "de": R(Color.FromArgb(0, 0, 0), 0, 0, 1, 1 / 3f); R(Color.FromArgb(221, 0, 0), 0, 1 / 3f, 1, 1 / 3f); R(Color.FromArgb(255, 206, 0), 0, 2 / 3f, 1, 1 / 3f); break;
                    case "fr": R(Color.FromArgb(0, 85, 164), 0, 0, 1 / 3f, 1); R(Color.White, 1 / 3f, 0, 1 / 3f, 1); R(Color.FromArgb(239, 65, 53), 2 / 3f, 0, 1 / 3f, 1); break;
                    case "it": R(Color.FromArgb(0, 146, 70), 0, 0, 1 / 3f, 1); R(Color.White, 1 / 3f, 0, 1 / 3f, 1); R(Color.FromArgb(206, 43, 55), 2 / 3f, 0, 1 / 3f, 1); break;
                    case "es": R(Color.FromArgb(170, 21, 27), 0, 0, 1, 1); R(Color.FromArgb(241, 191, 0), 0, 0.25f, 1, 0.5f); break;
                    case "pl": R(Color.White, 0, 0, 1, 0.5f); R(Color.FromArgb(220, 20, 60), 0, 0.5f, 1, 0.5f); break;
                    case "ru": R(Color.White, 0, 0, 1, 1 / 3f); R(Color.FromArgb(0, 57, 166), 0, 1 / 3f, 1, 1 / 3f); R(Color.FromArgb(213, 43, 30), 0, 2 / 3f, 1, 1 / 3f); break;
                    case "nl": R(Color.FromArgb(174, 28, 40), 0, 0, 1, 1 / 3f); R(Color.White, 0, 1 / 3f, 1, 1 / 3f); R(Color.FromArgb(33, 70, 139), 0, 2 / 3f, 1, 1 / 3f); break;
                    case "tr":
                        R(Color.FromArgb(227, 10, 23), 0, 0, 1, 1);
                        using (var wb = new SolidBrush(Color.White)) g.FillEllipse(wb, x + w * 0.22f, y + h * 0.25f, h * 0.5f, h * 0.5f);
                        using (var rb = new SolidBrush(Color.FromArgb(227, 10, 23))) g.FillEllipse(rb, x + w * 0.22f + h * 0.12f, y + h * 0.3f, h * 0.4f, h * 0.4f);
                        StarAt(g, x + w * 0.22f + h * 0.62f, y + h * 0.5f, h * 0.13f);
                        break;
                    case "pt": // Brasilien
                        R(Color.FromArgb(0, 156, 59), 0, 0, 1, 1);
                        using (var yb = new SolidBrush(Color.FromArgb(255, 223, 0)))
                            g.FillPolygon(yb, new[] { new PointF(x + w * 0.5f, y + h * 0.1f), new PointF(x + w * 0.92f, y + h * 0.5f), new PointF(x + w * 0.5f, y + h * 0.9f), new PointF(x + w * 0.08f, y + h * 0.5f) });
                        using (var bb = new SolidBrush(Color.FromArgb(0, 39, 118))) g.FillEllipse(bb, x + w * 0.5f - h * 0.22f, y + h * 0.28f, h * 0.44f, h * 0.44f);
                        break;
                    case "en": // Vereinigtes Königreich
                        R(Color.FromArgb(1, 33, 105), 0, 0, 1, 1);
                        using (var p = new Pen(Color.White, h * 0.2f)) { g.DrawLine(p, x, y, x + w, y + h); g.DrawLine(p, x + w, y, x, y + h); }
                        using (var p = new Pen(Color.FromArgb(200, 16, 46), h * 0.07f)) { g.DrawLine(p, x, y, x + w, y + h); g.DrawLine(p, x + w, y, x, y + h); }
                        R(Color.White, 0, 0.35f, 1, 0.3f); R(Color.White, 0.5f - 0.3f * h / w / 2 * 1f, 0, 0.3f * h / w, 1);
                        R(Color.FromArgb(200, 16, 46), 0, 0.41f, 1, 0.18f); R(Color.FromArgb(200, 16, 46), 0.5f - 0.18f * h / w / 2, 0, 0.18f * h / w, 1);
                        break;
                    default: R(Color.Gray, 0, 0, 1, 1); break;
                }
            }
            g.Restore(st);
            using (var p = new Pen(Color.FromArgb(60, 255, 255, 255), 1f)) using (var path = UI.Round(r, r.Height * 0.18f)) g.DrawPath(p, path);
        }
        static void StarAt(Graphics g, float cx, float cy, float rad)
        {
            var pts = new PointF[10];
            for (int i = 0; i < 10; i++) { double a = Math.PI * i / 5 - Math.PI; float rr = i % 2 == 0 ? rad : rad * 0.42f; pts[i] = new PointF(cx + (float)(Math.Cos(a) * rr), cy + (float)(Math.Sin(a) * rr)); }
            using (var b = new SolidBrush(Color.White)) g.FillPolygon(b, pts);
        }
    }
